            token: gift.token
        }, {require: false, transacting: options?.transacting});

        const data = this.toRow(gift);

        if (existing) {
            await existing.save(data, {
                transacting: options?.transacting,
                method: 'update',
                patch: true
            });
        } else {
            await this.model.add(data, {transacting: options?.transacting});
        }
    }

